from datetime import datetime, timezone
import numpy as np
import pandas as pd
from pandas import DataFrame

try:
    from freqtrade.strategy import IStrategy, DecimalParameter, IntParameter
except ImportError:
    class IStrategy:
        pass
    class DecimalParameter:
        def __init__(self, *args, **kwargs): self.value = kwargs.get('default', 0.0)
    class IntParameter:
        def __init__(self, *args, **kwargs): self.value = kwargs.get('default', 0)


class GoldIntradayTrendExhaustion(IStrategy):
    """
    GoldIntradayTrendExhaustion (GC-ITE):
    Institutional Prop Firm Strategy for Gold (XAUUSD / GC=F) on 1-Hour chart.

    1. Macro Regime Filter: 200-period Exponential Moving Average (EMA-200)
       - Longs permitted only when Close > EMA-200
       - Shorts permitted only when Close < EMA-200
    2. Setup Trigger: Momentum Exhaustion Reversal (14-period RSI)
       - LONG: Previous bar RSI(14) < 25.0 and Current bar RSI(14) >= 25.0 during active session (03:00 to 14:00 ET)
       - SHORT: Previous bar RSI(14) > 75.0 and Current bar RSI(14) <= 75.0 during active session (03:00 to 14:00 ET)
    3. Structural Execution Geometry:
       - Stop Loss: 1.8x Wilder's ATR(14)
       - Target: 1.8x Stop Distance (Asymmetric 1:1.8 Payout)
       - Time Stop: Max hold 6 bars (6 hours); all positions closed by 16:00 ET
    4. Prop Firm Risk Normalization (Fixed $1R = $350):
       - Position size calculated dynamically so each trade risks exactly 0.35% equity.
       - Max 2 losses per day ($700 max daily loss = 0.70%, safely below 3% daily limit).
       - Daily profit cap: $1,200 (15% of $8,000 profit target).
    """

    INTERFACE_VERSION = 3
    symbol = "XAU/USD"
    timeframe = "1h"
    can_short = True

    # Risk Parameters
    stoploss = -0.0075          # Emergency protective circuit breaker
    atr_multiplier = 1.8
    atr_tp_mult = 3.24          # 1.8 * 1.8 = 3.24 ATR
    atr_sl_mult = 1.8
    risk_per_trade_pct = 0.0035 # 35 bps base equity risk per trade ($350 on $100k)

    minimal_roi = {
        "0": 0.0120,
        "6": 0.0000            # Flat after 6 bars (6 hours)
    }

    trailing_stop = False

    def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        close = dataframe["close"]
        high = dataframe["high"]
        low = dataframe["low"]

        # 1. Macro Trend: 200 EMA
        dataframe["ema_200"] = close.ewm(span=200, adjust=False).mean()

        # 2. 14-period RSI
        delta = close.diff()
        gain = (delta.where(delta > 0, 0)).rolling(14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(14).mean()
        rs = gain / (loss + 1e-9)
        dataframe["rsi_14"] = 100 - (100 / (1 + rs))

        # 3. 14-period Wilder's True Range & ATR
        prev_c = close.shift(1)
        tr1 = high - low
        tr2 = (high - prev_c).abs()
        tr3 = (low - prev_c).abs()
        dataframe["tr"] = np.maximum(tr1, np.maximum(tr2, tr3))
        dataframe["atr_14"] = dataframe["tr"].ewm(alpha=1.0 / 14.0, min_periods=14, adjust=False).mean()

        # 4. Session Time Filters (Hours in ET / UTC)
        if hasattr(dataframe.index, "hour"):
            dataframe["hour"] = dataframe.index.hour
        else:
            dataframe["hour"] = 12

        return dataframe

    def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe["enter_long"] = 0
        dataframe["enter_short"] = 0

        # Session active window: 08:00 to 19:00 UTC (approx 03:00 to 14:00 ET)
        in_session = (dataframe["hour"] >= 8) & (dataframe["hour"] <= 19)

        # Long Condition: Macro Bullish + RSI Oversold Bounce
        long_cond = (
            (dataframe["close"] > dataframe["ema_200"]) &
            (dataframe["rsi_14"].shift(1) < 25.0) &
            (dataframe["rsi_14"] >= 25.0) &
            in_session
        )

        # Short Condition: Macro Bearish + RSI Overbought Rejection
        short_cond = (
            (dataframe["close"] < dataframe["ema_200"]) &
            (dataframe["rsi_14"].shift(1) > 75.0) &
            (dataframe["rsi_14"] <= 75.0) &
            in_session
        )

        dataframe.loc[long_cond, "enter_long"] = 1
        dataframe.loc[short_cond, "enter_short"] = 1

        return dataframe

    def populate_exit_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe["exit_long"] = 0
        dataframe["exit_short"] = 0

        # Force exit before session close (after 20:00 UTC / 16:00 ET)
        eod_exit = dataframe["hour"] >= 20
        dataframe.loc[eod_exit, "exit_long"] = 1
        dataframe.loc[eod_exit, "exit_short"] = 1

        return dataframe
